#include <map>
#include <string>

int main() {
    // Define a dictionary type supporting multiple translations
    typedef std::multimap<std::string, std::string> StrStrMMap;
    StrStrMMap dict;

    // Insert elements with duplicate keys
    dict.insert(std::make_pair("day", "Tag"));
    dict.insert(std::make_pair("day", "Jour")); // Duplicate key allowed
    dict.insert(std::make_pair("car", "Auto"));

    // Accessing elements (must use find or equal_range)
    auto range = dict.equal_range("day");
    // Iteration over all 'day' translations
    for (auto it = range.first; it != range.second; ++it) {
        // std::cout << it->second << " ";
    }
}
